package br.com.mecaniQA.api.Repository;
import br.com.mecaniQA.api.model.*; import br.com.mecaniQA.api.Mappers.ServicosResultSetMapper; import br.com.mecaniQA.api.Enums.*; import java.sql.*; import java.util.*; import java.time.*;
public class ServicosRepository extends JdbcSupport implements Repository<Servicos,Long>{private static final ServicosRepository INSTANCE=new ServicosRepository();public static ServicosRepository getInstance(){return INSTANCE;}public Servicos buscarServicoPorCodgio(Long id){return findById(id).orElse(null);}public Servicos cadastrarServico(Servicos x){return save(x);}public List<Servicos>listarTodosServicos(){return findAll();}public Servicos atualizarServico(Long id,Servicos x){x.setCodUnico(id);return update(x);}public Servicos deletarServico(Long id){Servicos x=buscarServicoPorCodgio(id);if(x!=null)deleteById(id);return x;}
 public Servicos save(Servicos x){long id=insert("INSERT INTO servicos(nome_servico,tempo_estimado_minutos,custo_tabelado) VALUES(?,?,?)",x.getNomeServico(),x.getTempoEstimadoMinutos(),x.getCustoTabelado());x.setCodUnico(id);return x;}public Optional<Servicos>findById(Long id){return query("SELECT * FROM servicos WHERE cod_unico=?",new ServicosResultSetMapper()::map,id).stream().findFirst();}public List<Servicos>findAll(){return query("SELECT * FROM servicos ORDER BY cod_unico",new ServicosResultSetMapper()::map);}public Servicos update(Servicos x){int n=execute("UPDATE servicos SET nome_servico=?,tempo_estimado_minutos=?,custo_tabelado=?,data_atualizacao=CURRENT_TIMESTAMP WHERE cod_unico=?",x.getNomeServico(),x.getTempoEstimadoMinutos(),x.getCustoTabelado(),x.getCodUnico());return n==0?null:x;}public void deleteById(Long id){execute("DELETE FROM servicos WHERE cod_unico=?",id);}public boolean existsById(Long id){return !query("SELECT cod_unico FROM servicos WHERE cod_unico=?",r->r.getLong(1),id).isEmpty();}private Servicos map(ResultSet r)throws SQLException{Servicos x=new Servicos(r.getString("nome_servico"),r.getInt("tempo_estimado_minutos"),r.getDouble("custo_tabelado"));setId(x,"codUnico",r.getLong("cod_unico"));x.setDataAtualizacao(time(r,"data_atualizacao"));return x;}}
